css:
.pkm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pkm-root,.pkm-root *,.pkm-root *::before,.pkm-root *::after{box-sizing:border-box}
.pkm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pkm-root img{display:block;border:0;max-width:none}
.pkm-root [hidden]{display:none!important}
.pkm-root .n1_1943{align-content:stretch;display:flex;gap:10px;height:24px;align-items:center;justify-content:center;padding-left:17px;padding-right:17px;padding-top:6px;padding-bottom:6px;position:relative;flex-shrink:0}
.pkm-root .nI1_1943_347_43003{position:absolute;height:24px;left:0;top:0;width:57px}
.pkm-root .x13{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pkm-root .nI1_1943_347_43006{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;display:flex;flex-direction:column;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;justify-content:center;line-height:0;font-style:normal;position:relative;flex-shrink:0;font-size:13px;color:color-mix(in srgb, var(--wa-text, rgb(255 255 255)) 90%, transparent);text-align:center;white-space:nowrap}
.pkm-root .nI1_1943_347_43006>p:first-of-type:last-of-type,.pkm-root .nI1_1943_347_43006>span:first-of-type:last-of-type{text-box-trim:trim-both;text-box-edge:cap alphabetic}
.pkm-root .x14{line-height:1}
.pkm-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pkm-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pkm-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pkm-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pkm-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pkm-root[data-theme="light"] .nI1_1943_347_43006{color:color-mix(in srgb, var(--wa-text, rgb(19 20 22)) 90%, transparent)}
